local _, addon = ...

addon.localeData.enUS.texts = {
 MARK={name="Mark of the Wild",ziel={"May the wilds watch over you, %s.","Root, wind and star strengthen you, %s.","*raises a hand toward %s as a gentle current stirs around them.*"},gruppe={"May the wilds watch over us.","Nature lend us strength and resilience.","*draws a slow circle in the air as leaves and wind answer the gesture.*"}},
 GIFT={name="Gift of the Wild",gruppe={"The blessing of the wilds be upon you all.","Many branches, one living whole.","*spreads both hands as the blessing settles over the group.*"}},
 THORNS={name="Thorns",ziel={"May the thorns guard you, %s.","Let every blow against you carry a price, %s.","*traces a protective gesture around %s as spectral thorns take shape.*"},gruppe={"The wilds are not defenseless.","Who reaches for us reaches into thorns.","*calls a ring of thorny growth around the companions.*"}},
 REJUVENATION={name="Rejuvenation",ziel={"New strength grow within you, %s.","Let nature ease your wounds, %s.","*rests a glowing hand near %s's wounds as fresh life begins to stir.*"},gruppe={"With every breath, strength returns.","Life returns one step at a time."}},
 REGROWTH={name="Regrowth",ziel={"Like new shoots after a storm, rise stronger, %s.","Nature close your wounds, %s.","*guides a surge of green life toward %s.*"},gruppe={"Even after the storm, the forest grows again.","Where there is life, healing can grow."}},
 HEALING_TOUCH={name="Healing Touch",ziel={"May the strength of the earth heal you, %s.","Stay with us, %s. Nature lends you strength.","*places a steady hand on %s and channels the calm strength of the wilds.*"},gruppe={"Nature grants us healing.","Life finds a way."}},
 TRANQUILITY={name="Tranquility",gruppe={"Be still and hear the forest breathe.","Let the noise of battle fade for a moment.","*lifts both hands as a calm green radiance settles over the companions.*"}},
 INNERVATE={name="Innervate",ziel={"Drink deeply from the current of life, %s.","May the wilds refill your spirit, %s.","*draws renewed natural power toward %s with a measured gesture.*"},gruppe={"The stream of life has not run dry.","From quiet springs comes new strength."}},
 REBIRTH={name="Rebirth",ziel={"Return to us, %s. Your path is not finished.","Life calls you by name, %s.","*kneels beside %s and calls upon the cycle of life to turn once more.*"},gruppe={"The cycle grants another chance.","Life calls a companion back."}},
 NATURES_GRASP={name="Nature's Grasp",gruppe={"The wilds wait for the next careless step.","Come closer. The earth is ready.","Whoever presses too close will feel the roots answer.","Nature reaches for those who threaten me.","The ground beneath my feet is more awake than it looks.","One step too far, and the wilds will hold fast.","*lowers a hand toward the ground as fine roots stir beneath the soil.*","*draws their fingers through the air; hidden vines answer below.*"}},
 ROOTS={name="Entangling Roots",ziel={"Roots of the earth, hold %s fast!","No further, %s. The ground itself holds you.","*drives a hand toward the earth as roots lash up around %s.*"},gruppe={"Roots of the earth, hold fast!","Where roots take hold, the charge ends."}},
 MOONFIRE={name="Moonfire",ziel={"Moonlight finds you, %s.","Silver fire burn upon you, %s.","*points toward %s as a shard of cold moonlight descends.*"},gruppe={"Silver fire breaks the darkness.","The moon answers my call."}},
 WRATH={name="Wrath",gruppe={"Nature raises its voice.","Wind and earth answer my call.","*draws the force of the wilds into a sudden, violent surge.*"}},
 BARKSKIN={name="Barkskin",gruppe={"Like old bark, I endure the storm.","Today I do not break.","*sets their stance as rough bark spreads across the skin.*"}},
 BEAR={name="Bear Form",gruppe={"With the bear's strength I guard my companions.","Claws ready. I hold the line.","*drops into a powerful bear form with a deep growl.*"}},
 CAT={name="Cat Form",gruppe={"Quiet steps and sharp senses guide me.","Claws need no long speeches.","*flows into feline form and lowers into a silent hunting stance.*"}},
 TRAVEL={name="Travel Form",gruppe={"The wind shows me the way.","Where one path ends, another begins.","*shifts into a swift traveling form and surges forward.*"}},
 AQUATIC={name="Aquatic Form",gruppe={"The current carries me.","Beneath the surface waits another wilderness.","*changes into an aquatic form and slips into the water.*"}},
 MOONKIN={name="Moonkin Form",gruppe={"Under moon and stars I keep the balance.","The stars are distant. Their power is not.","*takes on moonkin form beneath a shimmer of astral light.*"}},
 TREE={name="Tree of Life",gruppe={"My roots hold; my branches bring healing.","Come closer. There is room beneath these branches.","*roots into the ground as the form of the Tree of Life takes shape.*"}},
 FLIGHT={name="Flight Form",gruppe={"The sky opens its paths to me.","The ground can wait. The sky is calling.","*spreads newly formed wings and rises into the open air.*"}},
    -- Additional, individually written druid spell and animal-form dialogue
    STARFIRE = { name = "Starfire", gruppe = { "Even distant starlight finds a way through leaves and darkness.", "A spark from the heavens can split the night.", "*traces the path of a star between raised hands.*", "*looks above the canopy and calls down a silver beam.*" }, ziel = { "%s, even the farthest sky has found you." }, },
    INSECT_SWARM = { name = "Insect Swarm", gruppe = { "The smallest creatures of the wild have their own battles.", "A gentle buzz becomes a warning when nature rises.", "*brushes a flower and sends a cloud of wings from the undergrowth.*", "*turns a hand as though guiding a sea of tiny wings.*" }, ziel = { "%s, never underestimate the smallest wings." }, },
    HURRICANE = { name = "Hurricane", gruppe = { "The wind will not ask for permission.", "The treetops announced the storm before we arrived.", "*draws wide circles with both arms until the air begins to howl.*", "*plants both feet while leaves dance in the whirlwind.*" }, },
    FAERIE_FIRE = { name = "Faerie Fire", gruppe = { "Let the hidden stand revealed in the light of the glade.", "Even a silent shadow cannot escape a faerie spark.", "*draws a glowing leaf in the air.*", "*leaves a shimmering trail across the path.*" }, ziel = { "Hiding will not help you, %s." }, },
    FAERIE_FIRE_FERAL = { name = "Faerie Fire (Feral)", gruppe = { "Even claws understand the language of faerie light.", "The forest marks its enemies in a different glow.", "*shakes an uncanny glimmer from the fur.*", "*scratches a shining line across the earth.*" }, ziel = { "You are marked, %s. The forest sees you." }, },
    ECLIPSE = { name = "Eclipse", gruppe = { "Sun and moon do not quarrel. They share the same sky.", "Where one light fades, the other is born.", "*holds two palms together as a circle of light dims between them.*", "*lowers the head as though a shadow crossed the sun.*" }, },
    WILD_GROWTH = { name = "Wild Growth", gruppe = { "A single root seldom nourishes just one branch.", "Grow where battle has wounded the earth.", "*sends a green shimmer through the companions' ranks.*", "*touches the ground as a wave of young leaves spreads outward.*" }, },
    BLOOM = { name = "Bloom", gruppe = { "From the smallest seed, patience may raise a springtime.", "A flower needs no audience to give hope.", "*opens both hands as if a hidden bud were unfolding.*", "*lets the scent of fresh petals drift through the air.*" }, ziel = { "The wilds bloom for you, %s." }, },
    PRIMAL_BITE = { name = "Primal Bite", gruppe = { "The wilderness never apologizes for its hunger.", "One bite decides whether the hunt goes on.", "*draws the shoulders tight like a predator before its leap.*", "*snaps sharply at an opening in the opponent's guard.*" }, ziel = { "%s, you have met the wilderness's teeth." }, },
    LACERATE = { name = "Lacerate", gruppe = { "Not every scratch can be healed by a leaf.", "Claw marks linger after the fight moves elsewhere.", "*takes a low stance and delivers several tearing strikes.*", "*sweeps the claws forward in a short violent arc.*" }, ziel = { "You will remember this wound, %s." }, },
    REVIVE = { name = "Revive", gruppe = { "Sometimes life only sleeps behind a heavy door.", "Return. Roots and voices are still waiting for you.", "*kneels and rests a hand over a silent heart.*", "*speaks gently over a fallen companion as green light gathers.*" }, ziel = { "%s, the wilds are calling you back." }, },
    SWIFTMEND = { name = "Swiftmend", gruppe = { "Nature needs no long road when the danger is close.", "One moment of green warmth is sometimes enough.", "*sends a tightly gathered spark of healing forward.*", "*draws a healing glimmer out of the air and over a wound.*" }, ziel = { "%s, hold on. It will grow easier." }, },
    NATURES_SWIFTNESS = { name = "Nature's Swiftness", gruppe = { "When nature decides, it never hesitates.", "The wind never waits for a second thought.", "*straightens suddenly as the breeze seems to flow through the body.*", "*touches the earth and gathers focus in a single breath.*" }, },
    OMEN_OF_CLARITY = { name = "Omen of Clarity", gruppe = { "The answer lies between two breaths.", "The clearest choice often grows in silence.", "*closes the eyes and listens to a quiet inner voice.*", "*lets a soft glimmer travel across the fingertips.*" }, },
    SOOTHE_ANIMAL = { name = "Soothe Animal", gruppe = { "Easy, little heart. No one needs to fight today.", "Fear is no enemy to defeat with teeth.", "*lowers both shoulders and speaks quietly to the animal.*", "*holds an open hand steady and waits for a sign of trust.*" }, ziel = { "Easy, %s. I am not here to take anything." }, },
    HIBERNATE = { name = "Hibernate", gruppe = { "A deep sleep may be kinder than battle.", "Winter's stillness has no hurry.", "*draws a calm circle in the air and lowers the voice.*", "*sends a breath of frost and silence into the undergrowth.*" }, ziel = { "Sleep now, %s. The night is long enough." }, },
    REMOVE_CURSE = { name = "Remove Curse", gruppe = { "No dark word shall bind this heart.", "A curse is a story whose ending I can change.", "*brushes an invisible knot out of the air.*", "*wipes a dark shadow from a companion's shoulder.*" }, ziel = { "%s, that curse no longer belongs to you." }, },
    CURE_POISON = { name = "Cure Poison", gruppe = { "For every poison the earth grows a patient answer.", "The right root can overcome the wrong sting.", "*crushes a healing leaf between the fingers.*", "*lays a warm green hand above a wound.*" }, ziel = { "%s, let the wilds draw the poison away." }, },
    ABOLISH_POISON = { name = "Abolish Poison", gruppe = { "Let not another drop of venom steal your strength.", "I will guard this breath from its silent enemy.", "*pulls a dark stain out of the air with steady fingers.*", "*whispers an old healing verse as the green glow brightens.*" }, ziel = { "%s, this poison has no home here." }, },
    POUNCE = { name = "Pounce", gruppe = { "The shadow leaped before the branch moved.", "A silent landing is half the hunt.", "*crouches and springs out of cover.*", "*lands with claws extended and weight low.*" }, ziel = { "You saw me too late, %s." }, },
    SHRED = { name = "Shred", gruppe = { "Every defense leaves one opening. My claws know it.", "The quietest blow is the one never expected.", "*circles to the flank and tears forward.*", "*uses an enemy's turn to strike swiftly from behind.*" }, ziel = { "Guard your back, %s." }, },
    RAKE = { name = "Rake", gruppe = { "A short slash can leave a long memory.", "Claws write faster than any spoken word.", "*slashes three quick lines across the air.*", "*leaps sideways and strikes with a flick of the paw.*" }, ziel = { "Remember this warning, %s." }, },
    RIP = { name = "Rip", gruppe = { "The hunt is decided now.", "A predator never forgets the last opening.", "*commits to a deep and final claw attack.*", "*pushes off the ground and sweeps with a tearing strike.*" }, ziel = { "The hunt ends here, %s." }, },
    FEROCIOUS_BITE = { name = "Ferocious Bite", gruppe = { "A predator saves its strength for the final bite.", "Teeth are no threat. They are a promise.", "*tenses the jaw and lunges from close range.*", "*throws the body forward and snaps with startling speed.*" }, ziel = { "The space grows smaller, %s." }, },
    CLAW = { name = "Claw", gruppe = { "Small scars can tell of very long battles.", "The paw is quick, the claw is certain.", "*cuts through the air with a swift forepaw.*", "*lowers the body and makes a sharp claw strike.*" }, ziel = { "Never dismiss a small claw, %s." }, },
    MAUL = { name = "Maul", gruppe = { "The bear never asks whether a tree looks strong.", "Sometimes the wilderness answers with raw strength.", "*rises with massive shoulders and strikes downward.*", "*swings both heavy paws with deliberate force.*" }, ziel = { "That is the bear's answer, %s." }, },
    SWIPE = { name = "Swipe", gruppe = { "One blow can sweep away several shadows.", "The forest strikes wide when it defends itself.", "*sweeps a heavy paw through a broad arc.*", "*tears the air open with a mighty swing.*" }, },
    BASH = { name = "Bash", gruppe = { "Sometimes standing still is the gentlest answer.", "A heavy blow saves a thousand words.", "*rises and delivers one short, forceful strike.*", "*slams a paw forward and holds firm.*" }, ziel = { "A moment of quiet, please, %s." }, },
    GROWL = { name = "Growl", gruppe = { "This is my ground. My friends stand behind it.", "A single growl can explain enough.", "*plants the feet before the party and growls deeply.*", "*bares the teeth and draws attention away from the others.*" }, ziel = { "Over here, %s. I am waiting." }, },
    ENRAGE = { name = "Enrage", gruppe = { "Even a quiet forest has its storms.", "Patience does not always end gently.", "*digs claws into the ground and tenses every muscle.*", "*releases a deep and rumbling snarl.*" }, },
    DASH = { name = "Dash", gruppe = { "The road grows shorter when four paws take it.", "Wind in the fur, earth beneath the claws.", "*springs away before a leaf can reach the ground.*", "*weaves gracefully between the trees at full speed.*" }, },
    PROWL = { name = "Prowl", gruppe = { "A leaf rustles. I do not.", "Only the wilderness knows where I walk.", "*drops into the grass and disappears in the shadows.*", "*places each paw without snapping a twig.*" }, },
    FRENZIED_REGENERATION = { name = "Frenzied Regeneration", gruppe = { "A bear does not fall merely because life grows difficult.", "The earth returns what battle has taken.", "*breathes heavily, then draws the massive body upright.*", "*plants both paws and gathers the last reserves of strength.*" }, },
    CHALLENGING_ROAR = { name = "Challenging Roar", gruppe = { "If you seek a fight, look at me!", "My companions shall stand behind my shoulders.", "*lets out a thunderous roar across the glade.*", "*slams a paw into the ground and blocks the way.*" }, },
    FERAL_CHARGE = { name = "Feral Charge", gruppe = { "No cover can stop a determined bear.", "First the earth trembles. Then I arrive.", "*pushes off with the hind paws and charges ahead.*", "*drives one shoulder into a sudden opening.*" }, ziel = { "Here I come, %s." }, },
    DEMORALIZING_ROAR = { name = "Demoralizing Roar", gruppe = { "Courage does not sound like this growl.", "Even a forest full of foes can fall silent.", "*raises a heavy head and unleashes a rolling bellow.*", "*bristles the fur and fills the clearing with a roar.*" }, },
    SHAPE_SHIFT = { name = "Shapeshifting", gruppe = { "Skin is only one form that life may wear.", "I carry many shapes but only one memory.", "*bows the head as the body dissolves into green light.*", "*draws both hands inward as a new silhouette begins to wake.*" }, },
    REJUVENATING_BLOOM = { name = "Rejuvenating Bloom", gruppe = { "Even the smallest flower knows the way back to life.", "A fresh shoot between stones is enough to promise spring.", "*lets a single bud unfold between the fingers.*", "*scatters a tender green glow across a wound.*" }, ziel = { "%s, the wilds offer another beginning." }, },
}
